 1: import { useCallback, useState } from "react";
 2: 
 3: import { createInvoiceVa, InvoiceApiError } from "../services/invoice.service";
 4: import type { CreateInvoiceVaPayload, InvoiceVaData } from "../types/invoice";
 5: 
 6: export type ToastVariant = "error" | "success";
 7: 
 8: export interface ToastState {
 9:   message: string;
10:   variant: ToastVariant;
11: }
12: 
13: export interface UseCreateInvoiceVaResult {
14:   isLoading: boolean;
15:   error: string | null;
16:   vaData: InvoiceVaData | null;
17:   isModalOpen: boolean;
18:   isPaymentComplete: boolean;
19:   toast: ToastState | null;
20:   handleCreateVA: (payload: CreateInvoiceVaPayload) => Promise;
21:   markPaymentPaid: () => void;
22:   handlePaymentComplete: () => void;
23:   closeModal: () => void;
24:   clearToast: () => void;
25:   clearError: () => void;
26: }
27: 
28: export function useCreateInvoiceVa(): UseCreateInvoiceVaResult {
29:   const [isLoading, setIsLoading] = useState(false);
30:   const [error, setError] = useState(null);
31:   const [vaData, setVaData] = useState(null);
32:   const [isModalOpen, setIsModalOpen] = useState(false);
33:   const [isPaymentComplete, setIsPaymentComplete] = useState(false);
34:   const [toast, setToast] = useState(null);
35: 
36:   const clearToast = useCallback(() => setToast(null), []);
37:   const clearError = useCallback(() => setError(null), []);
38: 
39:   const closeModal = useCallback(() => {
40:     setIsModalOpen(false);
41:   }, []);
42: 
43:   const markPaymentPaid = useCallback(() => {
44:     setVaData((prev) => (prev ? { ...prev, status: "PAID" } : prev));
45:   }, []);
46: 
47:   const handlePaymentComplete = useCallback(() => {
48:     setIsPaymentComplete(true);
49:     setIsModalOpen(false);
50:     setToast({
51:       message: "Pembayaran berhasil diterima! Terima kasih.",
52:       variant: "success",
53:     });
54:   }, []);
55: 
56:   const handleCreateVA = useCallback(async (payload: CreateInvoiceVaPayload) => {
57:     setIsLoading(true);
58:     setError(null);
59:     setIsPaymentComplete(false);
60:     clearToast();
61: 
62:     try {
63:       const data = await createInvoiceVa(payload);
64:       setVaData(data);
65:       setIsModalOpen(true);
66:       setToast({
67:         message: "Virtual Account berhasil dibuat. Silakan selesaikan pembayaran.",
68:         variant: "success",
69:       });
70:     } catch (err) {
71:       const message =
72:         err instanceof InvoiceApiError
73:           ? err.message
74:           : err instanceof Error
75:             ? err.message
76:             : "Terjadi kesalahan tak terduga.";
77: 
78:       setError(message);
79:       setToast({ message, variant: "error" });
80:     } finally {
81:       setIsLoading(false);
82:     }
83:   }, [clearToast]);
84: 
85:   return {
86:     isLoading,
87:     error,
88:     vaData,
89:     isModalOpen,
90:     isPaymentComplete,
91:     toast,
92:     handleCreateVA,
93:     markPaymentPaid,
94:     handlePaymentComplete,
95:     closeModal,
96:     clearToast,
97:     clearError,
98:   };
99: }

 1: import { useCallback, useEffect, useRef, useState } from "react";
 2: 
 3: import { fetchInvoiceStatus, InvoiceApiError } from "../services/invoice.service";
 4: import type { InvoiceVaStatus } from "../types/invoice";
 5: 
 6: const POLL_INTERVAL_MS = 5000;
 7: 
 8: export interface UseInvoicePaymentStatusOptions {
 9:   orderId: string | null;
10:   /** Aktifkan polling saat modal terbuka */
11:   enabled: boolean;
12:   onPaid?: () => void;
13: }
14: 
15: export interface UseInvoicePaymentStatusResult {
16:   status: InvoiceVaStatus | null;
17:   isPaid: boolean;
18:   isChecking: boolean;
19:   checkError: string | null;
20:   checkStatus: () => Promise;
21: }
22: 
23: export function useInvoicePaymentStatus({
24:   orderId,
25:   enabled,
26:   onPaid,
27: }: UseInvoicePaymentStatusOptions): UseInvoicePaymentStatusResult {
28:   const [status, setStatus] = useState(null);
29:   const [isChecking, setIsChecking] = useState(false);
30:   const [checkError, setCheckError] = useState(null);
31:   const onPaidRef = useRef(onPaid);
32: 
33:   useEffect(() => {
34:     onPaidRef.current = onPaid;
35:   }, [onPaid]);
36: 
37:   const isPaid = status === "PAID";
38: 
39:   const checkStatus = useCallback(async (): Promise => {
40:     if (!orderId) {
41:       return null;
42:     }
43: 
44:     setIsChecking(true);
45:     setCheckError(null);
46: 
47:     try {
48:       const data = await fetchInvoiceStatus(orderId);
49:       setStatus(data.status);
50: 
51:       if (data.status === "PAID") {
52:         onPaidRef.current?.();
53:       }
54: 
55:       return data.status;
56:     } catch (err) {
57:       const message =
58:         err instanceof InvoiceApiError
59:           ? err.message
60:           : err instanceof Error
61:             ? err.message
62:             : "Gagal memeriksa status pembayaran.";
63: 
64:       setCheckError(message);
65:       return null;
66:     } finally {
67:       setIsChecking(false);
68:     }
69:   }, [orderId]);
70: 
71:   useEffect(() => {
72:     if (!enabled || !orderId || isPaid) {
73:       return;
74:     }
75: 
76:     void checkStatus();
77: 
78:     const intervalId = window.setInterval(() => {
79:       void checkStatus();
80:     }, POLL_INTERVAL_MS);
81: 
82:     return () => window.clearInterval(intervalId);
83:   }, [enabled, orderId, isPaid, checkStatus]);
84: 
85:   useEffect(() => {
86:     if (!enabled) {
87:       setStatus(null);
88:       setCheckError(null);
89:     }
90:   }, [enabled]);
91: 
92:   return {
93:     status,
94:     isPaid,
95:     isChecking,
96:     checkError,
97:     checkStatus,
98:   };
99: }

