 1: import { API_BASE_URL } from "../config/api";
 2: import type {
 3:   CreateInvoiceVaApiResponse,
 4:   CreateInvoiceVaPayload,
 5:   InvoiceStatusApiResponse,
 6:   InvoiceStatusData,
 7:   InvoiceVaData,
 8: } from "../types/invoice";
 9: 
10: export class InvoiceApiError extends Error {
11:   readonly statusCode: number;
12:   readonly responseCode?: string;
13: 
14:   constructor(message: string, statusCode: number, responseCode?: string) {
15:     super(message);
16:     this.name = "InvoiceApiError";
17:     this.statusCode = statusCode;
18:     this.responseCode = responseCode;
19:   }
20: }
21: 
22: function resolveErrorMessage(body: CreateInvoiceVaApiResponse, status: number): string {
23:   if (body.message) {
24:     return body.message;
25:   }
26: 
27:   if (status === 409) {
28:     return "Tagihan dengan nomor dokumen ini sudah pernah dibuat. Silakan cek instruksi pembayaran Anda.";
29:   }
30: 
31:   if (status >= 500) {
32:     return "Server sedang bermasalah. Silakan coba beberapa saat lagi.";
33:   }
34: 
35:   return "Gagal membuat Virtual Account. Periksa data Anda dan coba lagi.";
36: }
37: 
38: export async function createInvoiceVa(
39:   payload: CreateInvoiceVaPayload,
40: ): Promise {
41:   const response = await fetch(`${API_BASE_URL}/api/invoices/va`, {
42:     method: "POST",
43:     headers: {
44:       "Content-Type": "application/json",
45:       Accept: "application/json",
46:     },
47:     body: JSON.stringify(payload),
48:   });
49: 
50:   let body: CreateInvoiceVaApiResponse;
51: 
52:   try {
53:     body = (await response.json()) as CreateInvoiceVaApiResponse;
54:   } catch {
55:     throw new InvoiceApiError(
56:       "Respons server tidak valid. Pastikan backend berjalan.",
57:       response.status,
58:     );
59:   }
60: 
61:   if (!response.ok || !body.success || !body.data) {
62:     throw new InvoiceApiError(
63:       resolveErrorMessage(body, response.status),
64:       response.status,
65:       body.responseCode,
66:     );
67:   }
68: 
69:   return body.data;
70: }
71: 
72: export async function fetchInvoiceStatus(orderId: string): Promise {
73:   const encodedOrderId = encodeURIComponent(orderId);
74:   const response = await fetch(`${API_BASE_URL}/api/invoices/${encodedOrderId}/status`, {
75:     method: "GET",
76:     headers: { Accept: "application/json" },
77:   });
78: 
79:   let body: InvoiceStatusApiResponse;
80: 
81:   try {
82:     body = (await response.json()) as InvoiceStatusApiResponse;
83:   } catch {
84:     throw new InvoiceApiError(
85:       "Respons server tidak valid. Pastikan backend berjalan.",
86:       response.status,
87:     );
88:   }
89: 
90:   if (!response.ok || !body.success || !body.data) {
91:     throw new InvoiceApiError(
92:       body.message ?? "Gagal memeriksa status pembayaran.",
93:       response.status,
94:     );
95:   }
96: 
97:   return body.data;
98: }

