1: /** Format nominal tagihan ke Rupiah (integer, tanpa desimal). */
2: export function formatRupiah(amount: number): string {
3:   return new Intl.NumberFormat("id-ID", {
4:     style: "currency",
5:     currency: "IDR",
6:     minimumFractionDigits: 0,
7:     maximumFractionDigits: 0,
8:   }).format(amount);
9: }

