 1: import { motion, type Variants } from "framer-motion";
 2: import type { ReactNode } from "react";
 3: 
 4: type Direction = "up" | "down" | "left" | "right" | "none" | "scale";
 5: 
 6: type AnimateInProps = {
 7:   children: ReactNode;
 8:   className?: string;
 9:   delay?: number;
10:   direction?: Direction;
11:   duration?: number;
12:   once?: boolean;
13:   amount?: number | "some" | "all";
14: };
15: 
16: // Easing curve — smooth deceleration (tidak "bouncy")
17: const ease = [0.21, 0.47, 0.32, 0.98] as const;
