 38: 
 39:   --theme-foreground: #ffffff;
 40:   --theme-foreground-muted: #94a3b8;
 41: 
 42:   --theme-border: #1e293b;
 43: 
 44:   --section-padding-y: 6rem;
 45:   --transition-base: all 0.3s ease-in-out;
 46: }
 47: 
 48: /* ── Base ─────────────────────────────────────────────────────────── */
 49: @layer base {
 50:   html {
 51:     scroll-behavior: smooth;
 52:     scroll-padding-top: 5rem;
 53:     text-rendering: optimizeLegibility;
 54:     -webkit-font-smoothing: antialiased;
 55:     -moz-osx-font-smoothing: grayscale;
 56:   }
 57: 
 58:   body {
 59:     background-color: var(--theme-background);
 60:     color: var(--theme-foreground);
 61:     font-family: var(--font-sans);
 62:     overflow-x: hidden;
 63:     /* Subpixel hint untuk font lebih tajam di dark bg */
 64:     font-synthesis: none;
 65:   }
 66: 
 67:   h1,
 68:   h2,
 69:   h3,
 70:   h4,
 71:   h5,
 72:   h6 {
 73:     font-family: var(--font-heading);
 74:     letter-spacing: 0.03em;
 75:   }
 76: 
 77:   /* ── Focus ring global ───────────────── */
 78:   *:focus-visible {
 79:     outline: 2px solid var(--theme-accent);
 80:     outline-offset: 3px;
 81:     border-radius: 6px;
 82:   }
 83: 
 84:   /* ── Text selection ──────────────────── */
 85:   ::selection {
 86:     background-color: color-mix(in srgb, var(--theme-accent) 35%, transparent);
 87:     color: #ffffff;
 88:   }
 89:   ::-moz-selection {
 90:     background-color: color-mix(in srgb, var(--theme-accent) 35%, transparent);
 91:     color: #ffffff;
 92:   }
 93: 
 94:   /* ── Custom scrollbar ────────────────── */
 95:   ::-webkit-scrollbar {
 96:     width: 8px;
 97:     height: 8px;
 98:   }
 99:   ::-webkit-scrollbar-track {
100:     background: var(--theme-background);
101:   }
102:   ::-webkit-scrollbar-thumb {
103:     background: #1e293b;
104:     border-radius: 999px;
105:     border: 2px solid var(--theme-background);
106:     transition: background 0.2s;
107:   }
108:   ::-webkit-scrollbar-thumb:hover {
109:     background: var(--theme-accent);
110:   }
111: 
112:   /* Body copy — rata kiri-kanan (permintaan client) */
113:   #main-content
114:     :is(p, figcaption):where(
115:       [class*="leading-relaxed"],
116:       [class*="leading-[1.75]"],
117:       [class*="leading-[1.8]"]
118:     ):not(:where([class*="text-center"])),
119:   #main-content
120:     p:where([class*="max-w-"][class*="font-light"]):not(
121:       :where([class*="text-center"], [class*="bg-clip-text"])
122:     ),
123:   footer
124:     p:where([class*="leading-relaxed"]):not(:where([class*="text-center"])) {
125:     text-align: justify;
126:     text-wrap: pretty;
127:   }
128: 
129:   /* ── Skip link ───────────────────────── */
130:   .skip-link {
131:     position: absolute;
132:     left: -9999px;
133:     top: 0;
134:     z-index: 100;
135:     padding: 0.75rem 1.25rem;
136:     background-color: var(--theme-accent);
137:     color: #fff;
138:     font-weight: 600;
139:     text-decoration: none;
140:     border-radius: 0 0 0.5rem 0;
141:     transition: left 0.2s ease-in-out;
142:   }
143:   .skip-link:focus {
144:     left: 0;
145:     outline: none;
146:   }
147: }
148: 
149: /* ── Utilities ────────────────────────────────────────────────────── */
150: @layer utilities {
151:   .text-outline-white {
152:     -webkit-text-stroke: 1px rgba(255, 255, 255, 0.3);
153:     color: transparent;
154:   }
155:   /* Shine sweep — dipakai oleh Button, WhatsApp CTA, dll */
156:   .shine {
157:     position: relative;
158:     overflow: hidden;
159:   }
160:   .shine::before {
161:     content: "";
162:     position: absolute;
163:     inset: 0;
164:     transform: translateX(-100%);
165:     background: linear-gradient(
166:       90deg,
167:       transparent 0%,
168:       rgba(255, 255, 255, 0.12) 50%,
169:       transparent 100%
170:     );
171:     transition: transform 0.55s ease;
172:     pointer-events: none;
173:   }
174:   .shine:hover::before {
175:     transform: translateX(100%);
176:   }
177: 
178:   /* Glow text gradient — dipakai hero headline */
179:   .text-glow {
180:     text-shadow: 0 0 40px rgba(56, 152, 212, 0.4);
181:   }
182: 
183:   /* Glass card — consistent border+bg pattern */
184:   .glass {
185:     background: rgba(11, 17, 32, 0.5);
186:     backdrop-filter: blur(12px);
187:     border: 1px solid rgba(255, 255, 255, 0.06);
188:   }
189: 
190:   /* Subtle grid overlay — decorative bg pattern */
191:   .bg-grid {
192:     background-image:
193:       linear-gradient(rgba(255, 255, 255, 0.03) 1px, transparent 1px),
194:       linear-gradient(90deg, rgba(255, 255, 255, 0.03) 1px, transparent 1px);
195:     background-size: 64px 64px;
196:   }
197: 
198:   /* Noise texture overlay — optional depth on sections */
199:   .bg-noise {
200:     background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)' opacity='0.03'/%3E%3C/svg%3E");
201:     background-repeat: repeat;
202:     background-size: 200px 200px;
203:   }
204: 
205:   /* Animated gradient border — accent ring on interactive elements */
206:   .border-gradient {
207:     border: 1px solid transparent;
208:     background-clip: padding-box;
209:     position: relative;
210:   }
211:   .border-gradient::before {
212:     content: "";
213:     position: absolute;
214:     inset: -1px;
215:     border-radius: inherit;
216:     background: linear-gradient(
217:       135deg,
218:       rgba(56, 152, 212, 0.4),
219:       transparent 60%
220:     );
221:     z-index: -1;
222:     opacity: 0;
223:     transition: opacity 0.3s;
224:   }
225:   .border-gradient:hover::before {
226:     opacity: 1;
227:   }
228: }
229: 
230: /* ── Keyframe animations (CSS-only, zero JS) ─────────────────────── */
231: @keyframes float {
232:   0%,
233:   100% {
234:     transform: translateY(0px);
235:   }
236:   50% {
237:     transform: translateY(-8px);
238:   }
239: }
240: 
241: @keyframes float-slow {
242:   0%,
243:   100% {
244:     transform: translateY(0px) rotate(0deg);
245:   }
246:   33% {
247:     transform: translateY(-6px) rotate(1deg);
248:   }
249:   66% {
250:     transform: translateY(-3px) rotate(-1deg);
251:   }
252: }
253: 
254: @keyframes glow-pulse {
255:   0%,
256:   100% {
257:     opacity: 0.04;
258:     transform: scale(1);
259:   }
260:   50% {
261:     opacity: 0.08;
262:     transform: scale(1.08);
263:   }
264: }
265: 
266: @keyframes shimmer {
267:   0% {
268:     background-position: -200% center;
269:   }
270:   100% {
271:     background-position: 200% center;
272:   }
273: }
274: 
275: @keyframes fade-up {
276:   from {
277:     opacity: 0;
278:     transform: translateY(16px);
279:   }
280:   to {
281:     opacity: 1;
282:     transform: translateY(0);
283:   }
284: }
285: 
286: @keyframes spin-slow {
287:   from {
288:     transform: rotate(0deg);
289:   }
290:   to {
291:     transform: rotate(360deg);
292:   }
293: }
294: 
295: /* Utility classes untuk keyframes */
296: .animate-float {
297:   animation: float 4s ease-in-out infinite;
298: }
299: .animate-float-slow {
300:   animation: float-slow 6s ease-in-out infinite;
301: }
302: .animate-glow-pulse {
303:   animation: glow-pulse 6s ease-in-out infinite;
304: }
305: .animate-fade-up {
306:   animation: fade-up 0.5s ease-out both;
307: }
308: .animate-spin-slow {
309:   animation: spin-slow 12s linear infinite;
310: }
311: 
312: /* Shimmer loading skeleton */
313: .animate-shimmer {
314:   background: linear-gradient(
315:     90deg,
316:     rgba(255, 255, 255, 0.03) 0%,
317:     rgba(255, 255, 255, 0.08) 50%,
318:     rgba(255, 255, 255, 0.03) 100%
319:   );
320:   background-size: 200% auto;
321:   animation: shimmer 1.8s linear infinite;
322: }
323: 
324: /* ── Reduced motion ──────────────────────────────────────────────── */
325: @media (prefers-reduced-motion: reduce) {
326:   html {
327:     scroll-behavior: auto;
328:   }
329: 
330:   *,
331:   *::before,
