333:     animation-duration: 0.01ms !important;
334:     animation-iteration-count: 1 !important;
335:     transition-duration: 0.01ms !important;
336:   }
337: 
338:   /* Matikan parallax glow di MainLayout */
339:   .will-change-transform {
340:     will-change: auto !important;
341:     transform: none !important;
342:   }
343: }

